# POST /api/sheets/{sheetId}/periods/generate-fy — generate the twelve monthly periods of a fiscal year exactly as
# generate does, from the first day of the sheet's fiscal start month (the fiscal-start-month setting, 1 unless set) in
# the year given (yyyy, the FY<yyyy> the fiscal year is named) to the last day of the eleventh month after it. A year
# that is not yyyy is a 400 and writes nothing. Responds with how many were made.
validate:
  class: net.officefloor.hq.app.period.ValidateGenerateFiscalYear
  next: generate
generate:
  class: net.officefloor.hq.app.period.GeneratePeriods
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.period.RespondWithGeneratedPeriods
# POST /api/sheets/{sheetId}/import-openings — paste opening balances as lines of name,period,amount: a person on the
# sheet by name or alias, a period on the sheet, an amount of 0.00 or more with two decimals. Every line is checked
# first; a failing line, or no lines at all, is a 400 that writes nothing. Each line then adds its amount to the
# person's carried figure for the period (a closed period keeps the figure fixed when it was closed), written as
# OPENING_SET. Responds with how many lines went through.
validate:
  class: net.officefloor.hq.app.opening.ValidateImportOpenings
  govern: [ transaction ]
  next: add
add:
  class: net.officefloor.hq.app.opening.AddImportedOpenings
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.opening.RespondWithImportOpenings
package net.officefloor.hq.app.period;

import java.time.LocalDate;
import java.time.YearMonth;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

/** Reads the body: the year is yyyy. Publishes the fiscal year's dates for the period generator: from the first day
 *  of the sheet's fiscal start month in that year to the last day of the eleventh month after it. */
public class ValidateGenerateFiscalYear {
    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody GenerateFiscalYearRequest request,
            SettingRepository settings, Out<GeneratePeriodsValues> values) throws InvalidPeriodException {
        String text = request == null || request.year() == null ? "" : request.year().trim();
        if (!text.matches("\\d{4}")) {
            throw new InvalidPeriodException("The fiscal year must be a year yyyy");
        }
        YearMonth first = YearMonth.of(Integer.parseInt(text), settings.fiscalStartMonth(sheetId.trim()));
        LocalDate from = first.atDay(1);
        LocalDate to = first.plusMonths(11).atEndOfMonth();
        String by = request.by() == null ? "" : request.by().trim();
        values.set(new GeneratePeriodsValues(from, to, by));
    }
}
package net.officefloor.hq.app.period;

import java.time.YearMonth;
import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Stores one period per calendar month from the from-date's month to the to-date's month, each running from the
 *  first to the last day of its month and named yyyy-mm, and writes each as PERIOD_ADDED. A month whose name is
 *  already a period of the sheet, or whose days overlap one, is left out. */
public class GeneratePeriods {
    public void generate(@PathVariable("sheetId") String sheetId, @Val GeneratePeriodsValues values,
            PeriodRepository periods, Audit audit, Out<GeneratedPeriods> generated) {
        String sheet = sheetId.trim();
        int made = 0;
        YearMonth last = YearMonth.from(values.to());
        for (YearMonth month = YearMonth.from(values.from()); !month.isAfter(last); month = month.plusMonths(1)) {
            String name = month.toString();
            if (periods.nameTaken(sheet, name) || periods.overlaps(sheet, month.atDay(1), month.atEndOfMonth())) {
                continue;
            }
            Period period = periods.add(sheet, name, month.atDay(1), month.atEndOfMonth(), null);
            audit.record("PERIOD_ADDED sheet=" + period.sheetId() + " by=" + values.by() + " period=" + period.name()
                    + " from=" + period.from() + " to=" + period.to());
            made++;
        }
        generated.set(new GeneratedPeriods(made));
    }
}
package net.officefloor.hq.app.period;

/** How many periods were generated. */
public record GeneratedPeriods(int made) {
}
package net.officefloor.hq.app.period;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithGeneratedPeriods {
    public void respond(@Val GeneratedPeriods generated, ObjectResponse<GeneratedPeriods> response) {
        response.send(generated);
    }
}
package net.officefloor.hq.app.period;

/** Body of generating a fiscal year's periods: the year (yyyy, the calendar year its first day falls in), and who
 *  generates. */
public record GenerateFiscalYearRequest(String year, String by) {
}

